import{_ as i,l as r,o as l,c as s,v as e,p as n,x as t,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const M=JSON.parse('{"title":"MoE 训练 all-to-all","description":"","frontmatter":{"title":"MoE 训练 all-to-all","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/moe-training-all2all.md","filePath":"llm/moe-training-all2all.md","lastUpdated":1789023840000}'),m={name:"llm/moe-training-all2all.md"};function c(A,a,E,_,u,P){const o=r("Mermaid");return l(),s("div",null,[a[1]||(a[1]=e('<h1 id="moe-训练-all-to-all" tabindex="-1">MoE 训练 all-to-all <a class="header-anchor" href="#moe-训练-all-to-all" aria-label="Permalink to &quot;MoE 训练 all-to-all&quot;">​</a></h1><div class="epigraph"><p>专家住在不同卡上时，每个微批都要把 token 按路由结果置换过去再置换回来；这两次 All-to-All 是稀疏计算换来的税，日历必须把它们算进去。</p><footer>—— Lepikhin et al., GShard；Fedus et al., Switch Transformers</footer></div><p><a href="/llm/grad-accum-microbatch">上一课</a>表明，降微批、加累积会增加集合通信次数。稠密 TP 的 All-Reduce 已经贵；<a href="/llm/moe-routing">MoE 路由</a> 之后，专家并行还要在每个微批、每个 MoE 层做 dispatch 与 combine 两次 All-to-All。本课不重讲 top-\\(k\\) 怎么打分。缺口是训练时这条置换通信如何与 1F1B / 重叠 / 累积共存，以及容量、落后者如何把税变成墙。异步检查点从下一课开始转向故障，本课先把稳态通信税付清。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>GShard 与 Switch 把专家分到设备上，token 跟着专家走。体积 \\(\\propto b_{\\mathrm{micro}}\\times s\\times d\\times k\\)（再加容量空洞）。Ulysses 的 All-to-All 键是序列块；MoE 的键是专家 id，两者叠在同一模型里时，同一层可能连续打两种置换，网络队列更容易堵。1F1B 的阶段若把 MoE 层放在边界，阶段间激活发送与专家置换抢链路。</p><p>路由抖动会让每次微批的通信形状微变；实现常用固定容量 padding，把抖动变成空洞字节。空洞不参与有效 FLOPs，但参与带宽，MFU 看起来差。这是专家粒度课的通信-计算比在训练日历上的落地。</p><h3 id="累积把税乘开" tabindex="-1">累积把税乘开 <a class="header-anchor" href="#累积把税乘开" aria-label="Permalink to &quot;累积把税乘开&quot;">​</a></h3><p>每个微批独立路由、独立 All-to-All。\\(k_{\\mathrm{acc}}\\) 增大，优化器虽稀，网络次数线性涨。MoE 上「用累积换显存」可能让通信成为主词，应优先重计算、优先更大 \\(b_{\\mathrm{micro}}\\)、优先更少的 MoE 层跨节点。</p><p><span class="marginnote">All-to-All 不是 All-Reduce。实现错成规约会把不同专家的输入加在一起。对拍应用专家输出范数，而不只对总损失。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把 EP 组放在 NVLink 域，跨节点只走 DP 或 PP。Tutel、DeepSpeed-MoE、Megatron-MoE 一类实现提供分组 All-to-All 与容量掩码。调度上：先算路由（本地、便宜），post dispatch，用无关计算重叠，wait 后跑专家 GEMM，再 post combine。与 DualPipe 双流叠加时，两套微批的 All-to-All 必须分缓冲，避免专家 batch 混洗。</p><p>负载均衡（辅助损失或无辅助偏置）是为了让各专家 token 数接近容量，从而让 All-to-All 体积可预测。失衡时热专家所在卡变成计算落后者，下一课的 straggler 会先打在这里。</p><h3 id="与-pp、sp-的切分" tabindex="-1">与 PP、SP 的切分 <a class="header-anchor" href="#与-pp、sp-的切分" aria-label="Permalink to &quot;与 PP、SP 的切分&quot;">​</a></h3><p>MoE 层尽量完整放在一个流水阶段内，不要把 dispatch 与专家计算分到两段。Ulysses 的序列分片要在路由之前定义「token 属于哪张 SP 卡」；通常先 SP 再 EP，或采用框架已经验证的一种顺序，禁止实验里私自交换而不对拍。</p><p><span class="marginnote">Dropless MoE 取消容量丢弃，All-to-All 体积随负载上漂，日历更难重叠。需要动态形状或预留上限。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>稀疏 FFN 把 FLOPs 降到 \\(k\\) 个专家，但把规约通信换成不规则置换。训练步的墙上时间变成 \\(\\max(\\text{稠密注意力},\\text{专家 GEMM},\\text{两次 A2A})\\) 的组合。\\(k\\)、容量因子、\\(b_{\\mathrm{micro}}\\) 同时进入这个 max。路由崩溃时计算项变小、通信项因空洞仍在，比值恶化。</p>',17)),(l(),n(h,null,{default:t(()=>[d(o,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%9C%AC%E5%9C%B0%E8%B7%AF%E7%94%B1%22%5D%20--%3E%20D%5B%22Dispatch%20All-to-All%22%5D%0A%20%20D%20--%3E%20E%5B%22%E4%B8%93%E5%AE%B6%20GEMM%22%5D%0A%20%20E%20--%3E%20C%5B%22Combine%20All-to-All%22%5D%0A%20%20C%20--%3E%20RES%5B%22%E6%AE%8B%E5%B7%AE%E6%B5%81%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不解决卡死与掉卡：A2A 是同步障碍，一卡挂则组挂。那是弹性与故障率课。也不解决检查点里专家分片如何按不同 EP 度恢复——下一课格式。稳态下若 A2A 已经占总时间一半，应减 EP 跨度或减 MoE 层数，而不是再加梯度累积。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲路由公式；只补训练日历上的两次置换税。</li><li>累积与双流会乘开 All-to-All 次数；EP 组应留在高带宽域。</li><li>容量空洞占带宽；负载均衡也是网络平滑。</li><li>与 Ulysses 的 A2A 键不同，顺序要对拍。</li><li>出处：Lepikhin et al., GShard, 2020；Fedus et al., Switch, 2021；Hwang et al., Tutel。</li></ul>',4))])}const f=i(m,[["render",c]]);export{M as __pageData,f as default};
